    public List<Integer> uniqueDigits(List<Integer> x) {

        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < x.size(); i++) {
            int num = x.get(i);
            boolean hasEvenDigit = false;
            while (num > 0) {
                int digit = num % 10;
                if (digit % 2 == 0) {
                    hasEvenDigit = true;
                    break;
                }
                num /= 10;
            }
            if (!hasEvenDigit) {
                res.add(x.get(i));
            }
        }
        Collections.sort(res);
        return res;
    }
}

