class Solution {
    public String findMax(List<String> words) {

        String max = "";
        int maxCount = 0;
        for (String word : words) {
            int count = 0;
            Set<Character> set = new HashSet<>();
            for (char c : word.toCharArray()) {
                if (!set.contains(c)) {
                    count++;
                    set.add(c);
                }
            }
            if (count > maxCount) {
                maxCount = count;
                max = word;
            } else if (count == maxCount && word.compareTo(max) < 0) {
                max = word;
            }
        }
        return max;
    }
}

